// Simulate script output from your main pipeline
// In production this comes from the YouTube pipeline
return [{
  json: {
    run_id: Date.now().toString(),
    script: {
      title: 'Why the MG S5 EV is Perfect for Indonesian Roads',
      hook: 'Most people buying an EV in Indonesia are making a $5,000 mistake',
      tone: 'educational',
      segments: [
        {
          title: 'The Problem with Most EVs in Indonesia',
          narration: 'Indonesian roads are not like European roads. Potholes, floods, heat...',
          broll_suggestion: 'Indonesian city traffic, road conditions'
        },
        {
          title: 'How the MG S5 Solves This',
          narration: 'MG designed this car with Southeast Asian conditions in mind...',
          broll_suggestion: 'MG S5 driving on various road types'
        }
      ],
      conclusion: 'The MG S5 EV is not just affordable — it is built for this market.',
      cta: 'Drop your city in the comments'
    },
    markdown: '# Why the MG S5 EV is Perfect for Indonesian Roads\n\nMost people buying an EV in Indonesia are making a $5000 mistake...'
  }
}];

// Extract project ID from ArcReel response
const response = $input.first().json;
const projectId = response.id || response.project_id || response.data?.id;

if (!projectId) {
  throw new Error('ArcReel did not return a project ID: ' + JSON.stringify(response));
}

console.log('ArcReel project created:', projectId);

return [{
  json: {
    ...$('Mock Script Input').first().json,
    arcreel_project_id: projectId,
    arcreel_status: 'created',
    arcreel_url: `http://arcreel:1241/projects/${projectId}`
  }
}];

// Build final notification message
const script = $('Mock Script Input').first().json.script;
const projectId = $('Extract Project ID').first().json.arcreel_project_id;
const exportData = $('Export Video').first().json;

const videoUrl = exportData.video_url || 
                 exportData.download_url || 
                 `http://arcreel:1241/projects/${projectId}/export`;

const message = [
  '✅ *Video ready!*',
  '',
  `📹 *${script.title}*`,
  '',
  `🎬 Watch/download:`,
  videoUrl,
  '',
  `📱 ArcReel project:`,
  `http://YOUR_VPS_IP:1241/projects/${projectId}`
].join('\n');

return [{
  json: {
    notification: message,
    video_url: videoUrl,
    project_id: projectId,
    title: script.title
  }
}];
